"""traffic_env_generic.py : SUMO environment wrapper that works on ANY
single-intersection network (synthetic or a real OpenStreetMap import),
by auto-discovering the traffic light, its controlled lanes, and its
green phases at connection time instead of hardcoding lane names like
'N1_0'. Use this together with a network generated by SUMO's
osmWebWizard.py for a real intersection; keep traffic_env.py (the
hardcoded version) as your tested fallback for the synthetic demo.
"""
import os
import sys
import numpy as np

sys.path.append(os.environ.get('SUMO_HOME', '/usr/share/sumo') + '/tools')
import traci  # noqa: E402

from perception.perception import LaneDetector  # noqa: E402


def discover_intersection(tls_id=None):
    """Auto-detect the TLS id, its unique controlled lanes, and the list
    of 'green' phase indices from whatever program is currently loaded.
    Call this AFTER traci.start() / traci.simulationStep() at least once
    (some SUMO builds need a step before TLS state queries are reliable).
    """
    all_tls = traci.trafficlight.getIDList()
    if not all_tls:
        raise RuntimeError('No traffic lights found in this network -- '
                            'is this really a signalised intersection?')
    if tls_id is None:
        tls_id = all_tls[0]  # single-intersection project: take the first/only one

    controlled = traci.trafficlight.getControlledLanes(tls_id)
    lanes = list(dict.fromkeys(controlled))  # de-duplicate, keep order

    logic = traci.trafficlight.getAllProgramLogics(tls_id)[0]
    green_phases = []
    for i, phase in enumerate(logic.phases):
        state = phase.state
        # a "green" phase has at least one G/g and no y (yellow is a
        # transition phase, not a state the agent should select directly)
        if ('G' in state or 'g' in state) and 'y' not in state:
            green_phases.append(i)
    if len(green_phases) < 2:
        raise RuntimeError(f'Found only {len(green_phases)} green phase(s) for TLS '
                            f'{tls_id} -- check the network\'s tlLogic.')
    return tls_id, lanes, green_phases


class TrafficEnvGeneric:
    """Gym-style wrapper around a single signalised SUMO intersection,
    auto-adapting to whatever lanes/phases that intersection actually has."""

    def __init__(self, sumo_cfg, gui=False, min_green=10, yellow_fallback=3,
                 max_steps=2400, seed=None):
        self.sumo_bin = 'sumo-gui' if gui else 'sumo'
        self.sumo_cfg = sumo_cfg
        self.min_green = min_green
        self.yellow_fallback = yellow_fallback
        self.max_steps = max_steps
        self.seed = seed
        self.tls_id = None
        self.lanes = None
        self.green_phases = None
        self.detector = None
        self.state_dim = None
        self.action_dim = 2  # 0 = hold, 1 = advance to the next green phase

    def reset(self):
        if traci.isLoaded():
            traci.close()
        args = [self.sumo_bin, '-c', self.sumo_cfg, '--no-step-log', 'true',
                '--waiting-time-memory', '10000', '--time-to-teleport', '300']
        if self.seed is not None:
            args += ['--seed', str(self.seed)]
        traci.start(args)
        traci.simulationStep()  # one warm-up step before introspecting TLS state

        if self.tls_id is None:  # discover once, reuse across resets
            self.tls_id, self.lanes, self.green_phases = discover_intersection()
            jx, jy = traci.junction.getPosition(self.tls_id)
            self.detector = LaneDetector(self.lanes, origin=(jx, jy))
            self.state_dim = 2 * len(self.lanes) + len(self.green_phases) + 1
            print(f'[env] auto-detected TLS "{self.tls_id}" with '
                  f'{len(self.lanes)} lanes and {len(self.green_phases)} green phases')

        self.cur_phase_idx = 0  # index into self.green_phases
        traci.trafficlight.setPhase(self.tls_id, self.green_phases[0])
        self.step_count = 0
        self.phase_timer = 0
        self.prev_wait = 0.0
        self.last_cv_output = None
        self.last_reward_components = {}
        self.wait_log, self.queue_log, self.arrived_total = [], [], 0
        return self._get_state()

    def _log_step(self):
        w = sum(traci.lane.getWaitingTime(l) for l in self.lanes)
        q = sum(traci.lane.getLastStepHaltingNumber(l) for l in self.lanes)
        self.wait_log.append(w)
        self.queue_log.append(q)
        self.arrived_total += traci.simulation.getArrivedNumber()

    def _get_state(self):
        positions = []
        lane_dists = {}
        for lane in self.lanes:
            dists = []
            lane_len = traci.lane.getLength(lane)
            for vid in traci.lane.getLastStepVehicleIDs(lane):
                lane_pos = traci.vehicle.getLanePosition(vid)
                dists.append(max(0.0, lane_len - lane_pos))
                x, y = traci.vehicle.getPosition(vid)
                positions.append((x, y, 0))
            lane_dists[lane] = dists

        frame = self.detector.render_frame(positions)
        cv_out = self.detector.detect(frame, lane_dists)
        self.last_cv_output = cv_out

        counts = [cv_out[l]['count'] for l in self.lanes]
        queues = [cv_out[l]['queue'] for l in self.lanes]
        phase_onehot = [1.0 if self.cur_phase_idx == i else 0.0 for i in range(len(self.green_phases))]
        timer = [min(self.phase_timer / 60.0, 1.0)]

        state = np.array(counts + queues + phase_onehot + timer, dtype=np.float32)
        n = len(self.lanes)
        state[:2 * n] = state[:2 * n] / 20.0
        return state

    def _reward(self):
        wait = sum(traci.lane.getWaitingTime(l) for l in self.lanes)
        queue = sum(traci.lane.getLastStepHaltingNumber(l) for l in self.lanes)
        thru = sum(traci.lane.getLastStepVehicleNumber(l) for l in self.lanes)
        delta_wait = wait - self.prev_wait
        wait_term = -delta_wait
        queue_term = -0.25 * queue
        throughput_term = 0.10 * thru
        r = wait_term + queue_term + throughput_term
        self.prev_wait = wait
        self.last_reward_components = {
            'wait': float(wait),
            'delta_wait': float(delta_wait),
            'wait_term': float(wait_term),
            'queue': int(queue),
            'queue_term': float(queue_term),
            'throughput': int(thru),
            'throughput_term': float(throughput_term),
            'total': float(r),
        }
        return float(r)

    def _find_yellow_phase(self, from_green_idx):
        """Return the phase index right after a green phase in the program
        (SUMO convention: yellow follows green before the next green)."""
        logic = traci.trafficlight.getAllProgramLogics(self.tls_id)[0]
        n = len(logic.phases)
        nxt = (from_green_idx + 1) % n
        if 'y' in logic.phases[nxt].state:
            return nxt
        return None  # no explicit yellow defined; switch directly (some TLS omit it)

    def step(self, action):
        """action 0 = hold current green phase, 1 = advance to next green phase."""
        phase_before = self.cur_phase_idx
        target_idx = self.cur_phase_idx if action == 0 else \
            (self.cur_phase_idx + 1) % len(self.green_phases)
        switch_requested = target_idx != phase_before
        switch_allowed = switch_requested and self.phase_timer >= self.min_green
        yellow_used = False

        if switch_allowed:
            yellow_phase = self._find_yellow_phase(self.green_phases[phase_before])
            if yellow_phase is not None:
                yellow_used = True
                traci.trafficlight.setPhase(self.tls_id, yellow_phase)
                for _ in range(self.yellow_fallback):
                    traci.simulationStep()
                    self.step_count += 1
                    self._log_step()
            traci.trafficlight.setPhase(self.tls_id, self.green_phases[target_idx])
            self.cur_phase_idx, self.phase_timer = target_idx, 0

        traci.simulationStep()
        self.step_count += 1
        self._log_step()
        self.phase_timer += 1

        state = self._get_state()
        reward = self._reward()
        done = (self.step_count >= self.max_steps or
                traci.simulation.getMinExpectedNumber() <= 0)
        info = {
            'step': self.step_count,
            'requested_action': int(action),
            'action_name': 'HOLD' if action == 0 else 'SWITCH',
            'phase_before': int(self.green_phases[phase_before]),
            'phase_after': int(self.green_phases[self.cur_phase_idx]),
            'phase_index': int(self.cur_phase_idx),
            'switch_requested': bool(switch_requested),
            'switch_allowed': bool(switch_allowed),
            'applied_switch': bool(switch_allowed),
            'blocked_by_min_green': bool(switch_requested and not switch_allowed),
            'yellow_used': bool(yellow_used),
            'reward_components': dict(self.last_reward_components),
        }
        return state, reward, done, info

    def close(self):
        if traci.isLoaded():
            traci.close()
